import * as React from "react";

export type PlaySquareIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function PlaySquareIcon({ size = 20, ...props }: PlaySquareIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="4" width="16" height="16" rx="2" /><path d="M10 8.5 15.5 12 10 15.5Z" />
    </svg>
  );
}
